import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int a = Integer.parseInt(st.nextToken()); int b = Integer.parseInt(st.nextToken()); int countA = 0; int countB = 0; int countBoth = 0; st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { int val = Integer.parseInt(st.nextToken()); boolean divA = (val % a == 0); boolean divB = (val % b == 0); if (divA && divB) { countBoth++; } else if (divA) { countA++; } else if (divB) { countB++; } } if (countBoth > 0) { if (countA >= countB) { out.println("BOB"); } else { out.println("ALICE"); } } else { if (countA > countB) { out.println("BOB"); } else { out.println("ALICE"); } } } out.flush(); out.close(); } }